INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1710,'원자재 성분시험',1,'원자재 수입검사의 일환으로 원자재 주문 SPEC.에 대해 입고된 원자재 MTC로 C, Mn, S, P, Si 등 주요 성분 항목에 대해 합부여부를 시스템에서 판정하는 것','품질판정','Raw Material Ingredient Test',NULL,NULL,NULL,'["MES"]','용어집.xlsx 168행: 프로그램=MES 용어, 모듈=품질판정, 용어(변경전)=원자재 성분시험, 영문=Raw Material Ingredient Test',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1711,'원자재 성분보류판정',1,'원자재 성분시험에서 불합격된 제품은 원자재 성분 보류재가 되고, 보류된 제품을 품질담당자가 검사기준과 비교 및 고객과 협의하여 합부여부를 판정하는 것','품질판정','Raw Material Ingredient Hold Judgement',NULL,NULL,NULL,'["MES"]','용어집.xlsx 169행: 프로그램=MES 용어, 모듈=품질판정, 용어(변경전)=신규, 영문=Raw Material Ingredient Hold Judgement',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1712,'시편모니터링',1,'시험실에서 재질시험을 하기 위해 시편의 채취지시,입고,시험대기,시험완료 등의 tracking을 모니터링하는 것. 1개의 Coil에 대하여 시편채취부터 종합판정 완료까지의 진행상태를 관리하기 위함.','품질판정','Sample Monitoring',NULL,NULL,NULL,'["MES"]','용어집.xlsx 170행: 프로그램=MES 용어, 모듈=품질판정, 용어(변경전)=신규, 영문=Sample Monitoring',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1713,'재질시험',1,'공정에서 채취한 시편을 시험실에서 HRB, ERI, YP, TS, EL 등을 시험하는 것. 즉, 1개의 Coil제품에 대해 인장, 경도, 에릭슨에 대한 시험 및 도금제품에 한하여 도금부착량을 광의로 포함하며, 시험실적으로 수요가요구 재질사양 범위를 Check함','품질판정','MaterialQuality Test',NULL,'["제품시험관리"]',NULL,'["MES"]','용어집.xlsx 171행: 프로그램=MES 용어, 모듈=품질판정, 용어(변경전)=제품시험관리, 영문=MaterialQuality Test',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
