INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1716,'종합판정',1,'제품의 입고시점에 화학성분, 외관, 재질, 칼라물성판정을 종합하여 등급결정 기준으로 정품, 주문외품, 급외품 등으로 분류하는것. 제품을 생산하여 고객에 판매를 위하여 최종제품의 등급을 결정하는 것으로 정품(A급)만 "해당주문고객"에게 판매가능함.','품질판정','Synthesize Judgement',NULL,NULL,NULL,'["MES"]','용어집.xlsx 175행: 프로그램=MES 용어, 모듈=품질판정, 용어(변경전)=신규, 영문=Synthesize Judgement',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
