INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1834,'예비품',1,'설비에 직접 장탈착되어 운용되는 자재로 설비수리 후 교체 대상인 자재. 설비고장 시 수리를 위해 항상 사용 가능한 수준의 재고를 유지하여 관리함','설비관리 (PM)','Spare Part',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 308행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Spare Part'||char(10)||'표준용어.xls no.6945: 시스템=ERP, 체인한글명=공통, 표준용어=예비품, 영문 Full Name=Required, 용어구분=보조어, 부문=ERP, 등록일=2011-10-20',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1835,'예비품',2,'Material Type에 의해 구분된 부자재 유형 중 정비/설비부서에서 사용하는 설비관련 부품 및 기자재를 칭함. 정기구매의 여부에 따라 안전재고 및 비안전재고로 구분하여 입고후 수량 및 금액관리가 이루어지는 품목군. 예비품중 안전재고는 중앙창고에서 안전재고 수량에 근거하여 구매청구가 이루어지며, 비안전재고는 정비/설비부서에서 직접 청구함.','자재관리 (MM)',NULL,NULL,NULL,NULL,'["ERP"]','용어집.xlsx 562행: 프로그램=ERP 용어, 모듈=자재관리 (MM)',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1836,'BOM',2,'정비를 위해 사용되는 BOM은 3가지 종류가 있음. 특정 기능위치에만 사용되는 자재를 BOM으로 구성할 경우 기능위치BOM, 특정 설비에 사용되는 자재를 BOM으로 구성한 경우는 설비BOM, 특정 기능위치, 설비를 지정 하지 않고 동일유형의 기능위치, 설비에 대해 자재마스터를 정의 하고 그 자재에 대해 BOM을 구성하는 자재BOM이 있음','설비관리 (PM)','Bill Of Material','BOM',NULL,NULL,'["ERP"]','용어집.xlsx 309행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문약어=BOM, 영문=Bill Of Material',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1837,'측정지점',1,'설비의 상태를(Condition)를 기술하는 물리적, 논리적 위치 (예, rotor shaft의 회전수, 압력용기에서 나오는 냉각수의 온도)로 기능위치, 설비 별로 정의함.','설비관리 (PM)','Measuring Point',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 310행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Measuring Point',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
