INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1839,'정비전략',1,'계획된 점검정비 작업의 일련의 순서(또는 주기설정)에 대한 규칙을 정의해 놓은 것. 정비전략은 점검정비에 대한 일정계획에 대한 일반적인 정보를 포함하고 있으며, 직무리스트(Task List)에 할당되어 작업별 주기 설정에 활용됨','설비관리 (PM)','Maintenance Strategy',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 312행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Maintenance Strategy',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1840,'정비계획',1,'정비계획은 실제 작업을 수행하는 조직별로 정비작업을 수행할 대상 설비,기능위치, 일정계획을 위한 변수값 정의, 적용할 직무리스트 등을 정의한 것. 정의된 내용에 따라 일정계획을 수행하면 해당 주기에 오더가 자동 생성 된다.','설비관리 (PM)','Maintenance Plan',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 313행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Maintenance Plan',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
