INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1843,'오더',1,'설비의 기능이상, 고장 발생 시 설비를 이상적인 조건으로 회복시키기 위한 점검/정비 작업 지시서','설비관리 (PM)','Order','ORD',NULL,NULL,'["ERP","MES"]','용어집.xlsx 316행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Order'||char(10)||'표준용어.xls no.4350: 시스템=MES, 체인한글명=MES공통, 표준용어=오더, 영문 Full Name=Order, 항목 ID=ORD, 용어구분=보조어, 부문=M00, 등록일=2009-11-03',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1844,'확정',2,'오더에 의거 작업을 수행 한 후 작업완료보고를 하는 행위. 오더에 지정된 모든 작업이 완료 된 경우 최종확정(Final Confirm) 이라 하고 일부작업만 완료 된 경우 부분확정(Partial Confirm)이라 함. 오더의 시스템 상태는 CNF, PCNF 로 표기함','설비관리 (PM)','Confirm',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 318행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Confirm',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1845,'기술적 완료',1,'작업자가 작업완료보고한 내용에 대해서 주임 또는 팀장이 오더를 완료처리하는 행위. 오더의 기술적 완료는 오더 건별로 완료처리해야 하며 기술적 완료 후에는 오더의 내용을 수정 할 수 없고 단지 비용의 기표는 가능함. 오더의 시스템상태는 TECO로 표기함','설비관리 (PM)','Technical Completion',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 319행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Technical Completion',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1846,'정산',1,'오더에 집계된 금액을 정의된 정산대상(코스트센터, Internal Order)으로 전기하는 것. 투자오더의 경우 Internal Order로 그외의 오더는 코스터센터로 정산함. 오더 정산은 오더 건별로 하는 것이 아니라 매월 1회 일괄적으로 수행되며 오더에 비용이 없는 경우 정산에 영향을 미치지 않음.','설비관리 (PM)','Settlement','STT',NULL,NULL,'["ERP","MES"]','용어집.xlsx 320행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Settlement'||char(10)||'표준용어.xls no.5501: 시스템=MES, 체인한글명=MES공통, 표준용어=정산, 영문 Full Name=Settlemen, 항목 ID=STT, 용어구분=보조어, 부문=M00, 등록일=2009-11-03',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
