INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1848,'비지니스완료',1,'오더에 실적비용이 모두 정산된 경우, 오더에 실적비용이 없는 경우에만 비지니스완료 가능하며, 비지니스완료가 되면 더 이상의 비용기표는 불가하고 오더 시스템 상태는 CLSD로 표기됨. 비즈니스 완료는 오더 건별로 수행 하는 것이 아니고 기술적완료 후 2~3개월이 지난 오더를 일괄 비지니스완료 처리함','설비관리 (PM)','Business Completion',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 321행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Business Completion',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
