INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1852,'구조 유형',1,'자재BOM을 생성한 경우 BOM의 헤더품목으로 지정되는 자재는 동일한 설비유형의 모든설비를 통칭하게 되고 이러한 자재를 구조유형 자재라고 함. 이 자재를 기능위치 또는 설비마스터에 구조유형 필드에 지정하면 같은 유형의 모든 설비에 BOM을 구성할 수 있음','설비관리 (PM)','Construction Type',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 325행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Construction Type',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
