INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1855,'설비유형',1,'동종 유사 설비에 대한 그룹. 설비유형은 다수의 설비를 그룹하여 숫자를 줄여 관리의 편의성을 도모하기 위해 정의함. (예: 설비유형별 고장분류코드 정의, 직무리스트 정의, 측정지점 정의 등)','설비관리 (PM)','Equipment Type',NULL,NULL,NULL,'["ERP"]','용어집.xlsx 328행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문=Equipment Type',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1856,'평균고장 발생간격',1,'설비의 설치 이후 또는 수리 이후 고장이 다시 발생하기 까지의 평균시간. MTBF값이 클수록 설비의 고장발생 후 고장의 재 발생까지 오랜 시간이 소요됨을 나타내므로 효율적이라 말 할 수 있음','설비관리 (PM)','Mean Time Between Failure','MTBF',NULL,NULL,'["ERP"]','용어집.xlsx 329행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문약어=MTBF, 영문=Mean Time Between Failure',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1857,'평균고장 수리시간',1,'설비의 고장이 발생하였을 때 설비의 성능을 정상화하는데 까지 소요된 시간. MTTR 값이 작을수록 설비의 수리를 신속하게 수행 하였음을 말한다.','설비관리 (PM)','Mean Time To Repair','MTTR',NULL,NULL,'["ERP"]','용어집.xlsx 330행: 프로그램=ERP 용어, 모듈=설비관리 (PM), 영문약어=MTTR, 영문=Mean Time To Repair',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
