INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(1992,'To-Be Model',1,'현재 모습을 As-Is라 한다면 향후 혁신을 통해 변화되어야 할 모습을 To-Be라 하며, To-Be 모델은 PI를 통해 변화될 프로세스 흐름도와 이에 따라 변경될 업무 절차, 역할, 제도 등을 종합적으로 설계한 ‘변화 모습 정의서’라고 할 수 있음','공통용어',NULL,NULL,NULL,NULL,NULL,'용어집.xlsx 475행: 프로그램=공통용어, 모듈=공통용어',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
