INSERT INTO "TB_MDM_TERM"("TERM_ID","TERM_NAME","SENSE_NO","DEFINITION","CONTEXT","ENG_NAME","ENG_ABBR","SYNONYMS","ALIASES","SYSTEMS","STD_BASIS","OWNER_DEPT","OWNER_ID","SRC_ORIGIN","EMBEDDING","EMBEDDING_MODEL","C_USR_ID","C_AT","C_SVC_ID","C_PGM_ID","U_USR_ID","U_AT","U_SVC_ID","U_PGM_ID","VER") VALUES(2047,'Backflush',1,'생산에 사용된 투입자재를 제품(또는 반제품)의 생산 확정시 자동으로 불출 시키는 것을 말함. BOM에 정의된 수량에 근거하여 불출 시키기 때문에 조립산업처럼 BOM 상의 부품의 소요량이 정확하게 관리되는 산업에서 자재불출 방법으로 많이 사용함.','표준화/생산관리 (MD/PP)',NULL,NULL,NULL,NULL,'["ERP"]','용어집.xlsx 568행: 프로그램=ERP 용어, 모듈=표준화/생산관리 (MD/PP)',NULL,NULL,'용어집.xlsx 2026-10-02',NULL,NULL,'dict-std',1790904184338,'dict-std','apply_dict_std','dict-std',1790904184338,'dict-std','apply_dict_std',0);
